// A consolidated act is immutable — when the EU consolidates again it gets a new
// CELEX id. So a change here is either a new consolidation or an amended text, and
// either way the sha256 of the manifest moves. Nothing downstream runs when it hasn't.
const payload = JSON.parse($input.first().json.stdout.trim().split('\n').pop());
const previous = $getWorkflowStaticData('global');
const changed = previous.digest !== payload.digest;
previous.digest = payload.digest;
previous.checked_at = new Date().toISOString();
return [{ json: { changed, digest: payload.digest, sources: payload.sources } }];

// One item per affected job, and nothing when none are. An empty array here is the
// normal outcome: most consolidations touch articles no stored report ever cited.
const payload = JSON.parse($input.first().json.stdout.trim().split('\n').pop());
return (payload.affected || []).map((job) => ({ json: job }));

const items = $input.all();
const requeued = items.filter((i) => (i.json.statusCode || 0) < 300).length;
return [{ json: {
  digest: $('Did the corpus change?').first().json.digest,
  affected: items.length,
  requeued,
  refused: items.length - requeued,
} }];

// The no-change path still reports, so a silent week is distinguishable from a
// workflow that stopped running.
return [{ json: { digest: $json.digest, affected: 0, requeued: 0, refused: 0, unchanged: true } }];
